{"content": "import openpyxl, re, os

base = r"C:\Users\24380\Downloads\烧烤\兵哥烧烤菜单"
wb = openpyxl.load_workbook(os.path.join(base, "兵哥烧烤价格.xlsx"))
ws = wb["Sheet1"]
new = []
for r in range(2, ws.max_row + 1):
    n, c, p = ws.cell(r, 2).value, ws.cell(r, 3).value, ws.cell(r, 4).value
    if n:
        new.append((str(n), p))

wb2 = openpyxl.load_workbook(os.path.join(base, "兵哥烧烤_菜品价格表.xlsx"), data_only=True)
ws2 = wb2["菜单明细"]
old = []
for r in range(5, ws2.max_row + 1):
    n, p = ws2.cell(r, 3).value, ws2.cell(r, 4).value
    if n and isinstance(p, (int, float)):
        old.append((str(n), p))

def key(s):
    s = str(s).strip()
    s = re.sub(r"[（(].*?[)）]", "", s)
    s = re.sub(r"^[0-9]+\.", "", s)
    for pre in ["炭烤", "碳烤", "烤", "手工", "现串", "香辣", "泡椒", "蒜蓉", "奶香", "广式", "切片", "手撕干"]:
        while s.startswith(pre):
            s = s[len(pre):]
    s = s.replace("把串", "").replace("小串", "").replace("串", "")
    s = s.replace("大", "").replace("小", "")
    return s

oldm = {}
for n, p in old:
    oldm.setdefault(key(n), []).append((n, p))
newm = {}
for n, p in new:
    newm.setdefault(key(n), []).append((n, p))

lines = []
lines.append("== 价格有变化 ==")
for k in newm:
    if k in oldm:
        op = {p for _, p in oldm[k] if isinstance(p, (int, float))}
        np_ = {p for _, p in newm[k] if isinstance(p, (int, float))}
        if op and np_ and op != np_:
            lines.append(f"{k}: 旧{oldm[k]} -> 新{newm[k]}")
lines.append("\n== 新表有旧表无 ==")
for k in newm:
    if k not in oldm:
        lines.append(f"{newm[k]}")
lines.append("\n== 旧表有新表无 ==")
for k in oldm:
    if k not in newm:
        lines.append(f"{oldm[k]}")

with open(r"C:\Users\24380\Documents\deepseek-harness\default-workspace\diff2.txt", "w", encoding="utf-8") as f:
    f.write("\n".join(lines))
print("ok")
", "file_path": "C:\Users\24380\Documents\deepseek-harness\default-workspace\diff2.py"}

